import numpy as np
import pandas as pd
g=pd.read_csv("guests_churn.csv")
X=g[["tenure_months","visits_90d","days_since_last","complaints"]].to_numpy(float);X=(X-X.mean(axis=0))/X.std(axis=0)
class TinyNet:
    def __init__(self,sizes,seed=0):
        rng=np.random.default_rng(seed);self.Ws=[];self.bs=[]
        for a,b in zip(sizes[:-1],sizes[1:]):
            self.Ws.append(rng.normal(size=(a,b))*np.sqrt(2/a));self.bs.append(np.zeros(b))
    def forward(self,X):
        A=X
        for i,(w,b) in enumerate(zip(self.Ws,self.bs)):
            A=A@w+b
            if i<len(self.Ws)-1: A=np.maximum(0,A)
        return A.ravel()
    def n_params(self):
        return sum(p.size for p in self.Ws+self.bs)
net=TinyNet([4,16,8,1]);n_par=net.n_params();z=net.forward(X[:5]);out_shape=z.shape;p=np.round(1/(1+np.exp(-z)),3)

